H["@lsp.type.string"] = { fg = "#a3daa3" }
H["@lsp.type.number"] = { fg = "#e8c98a" }
H["@lsp.type.comment"] = { fg = "#958ca9", italic = true }
H["@lsp.mod.deprecated"] = { fg = "#958ca9", strikethrough = true }

for group, spec in pairs(H) do
  vim.api.nvim_set_hl(0, group, spec)
end

-- Terminal palette: ANSI 0-15 exactly as the kitty port.
vim.g.terminal_color_0 = "#2c233c"
vim.g.terminal_color_1 = "#f06a6a"
vim.g.terminal_color_2 = "#a3daa3"
vim.g.terminal_color_3 = "#e8c98a"
vim.g.terminal_color_4 = "#8fb0f2"
vim.g.terminal_color_5 = "#fd7ca5"
vim.g.terminal_color_6 = "#9ed0c4"
vim.g.terminal_color_7 = "#beb9c9"
vim.g.terminal_color_8 = "#382f4a"
vim.g.terminal_color_9 = "#ed5858"
vim.g.terminal_color_10 = "#87cf8e"
vim.g.terminal_color_11 = "#dcbb6d"
vim.g.terminal_color_12 = "#7da4f4"
